import{_ as a,o as d,c as r,a2 as e}from"./chunks/framework.CqpfiAoK.js";const q=JSON.parse('{"title":"হেং ইয়ানঝোউ মহাবিশ্বের সার্বিক পরিচিতি","description":"","frontmatter":{},"headers":[],"relativePath":"bn/0000-衡元宙宇宙总览.md","filePath":"bn/0000-衡元宙宇宙总览.md"}'),o={name:"bn/0000-衡元宙宇宙总览.md"};function l(i,t,h,n,s,_){return d(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="হেং-ইয়ানঝোউ-মহাবিশ্বের-সার্বিক-পরিচিতি" tabindex="-1">হেং ইয়ানঝোউ মহাবিশ্বের সার্বিক পরিচিতি <a class="header-anchor" href="#হেং-ইয়ানঝোউ-মহাবিশ্বের-সার্বিক-পরিচিতি" aria-label="Permalink to &quot;হেং ইয়ানঝোউ মহাবিশ্বের সার্বিক পরিচিতি&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>00</td></tr><tr><td>মডিউল</td><td>মূল নীতি ও কোর সেটিং</td></tr><tr><td>মূল কীওয়ার্ড</td><td>হেং ইয়ানঝোউ, নোঙর বিন্দু, সহজীবন, হাজারো জাতি, মূল উৎস</td></tr></tbody></table><h2 id="_1-মহাবিশ্বের-মৌলিক-সংজ্ঞা" tabindex="-1">1. মহাবিশ্বের মৌলিক সংজ্ঞা <a class="header-anchor" href="#_1-মহাবিশ্বের-মৌলিক-সংজ্ঞা" aria-label="Permalink to &quot;1. মহাবিশ্বের মৌলিক সংজ্ঞা&quot;">​</a></h2><p>দশ হাজার আত্মা ও ভারসাম্যপূর্ণ নোঙরের মূল মহাবিশ্ব, সংক্ষেপে &quot;হেং ইয়ানঝোউ&quot;, হলো নোঙর সহজীবী সভ্যতা যে মহাবিশ্বে বাস করে এবং শাসন করে তার সম্পূর্ণ অঞ্চল। হেং ইয়ানঝোউ কোনো একক ভৌতিক স্থান নয়, বরং বস্তুগত বিমান, শক্তি স্তর, চেতনা অঞ্চল এবং নিয়ম জালের সম্মিলিত গঠনে তৈরি একটি যৌগিক অস্তিত্ব। এর নামের &quot;দশ হাজার আত্মা&quot; বলতে বোঝানো হয়েছে সকল প্রকার উপলব্ধি ও বিবর্তন সম্ভাবনা সম্পন্ন জীব-রূপকে; &quot;ভারসাম্যপূর্ণ নোঙর&quot; বলতে মহাবিশ্বের ভারসাম্য বজায় রাখার নোঙর বিন্দু প্রক্রিয়াকে; এবং &quot;মূল মহাবিশ্ব&quot; বলতে এই মহাবিশ্বের মূল নিয়মের উপর ভিত্তি করে গঠিত এবং সহজীবী বিবর্তনকে দিকনির্দেশক হিসেবে গ্রহণ করা মৌলিক বৈশিষ্ট্যকে বোঝানো হয়েছে।</p><p>হেং ইয়ানঝোউের মূল বৈশিষ্ট্য হলো এর &quot;বিবর্তনযোগ্যতা&quot;। ঐতিহ্যগত লুণ্ঠনমূলক মহাবিশ্ব-দর্শনে মহাবিশ্বকে সীমিত সম্পদের শিকারক্ষেত্র হিসেবে বিবেচনা করার বিপরীতে, হেং ইয়ানঝোউ বিশ্বাস করে যে মহাবিশ্ব নিজেই একটি জীবন্ত সত্তা, এবং এর এনট্রপি বৃদ্ধির প্রক্রিয়া সুশৃঙ্খল সহজীবী জালের মাধ্যমে প্রত্যাবর্তন ও নিয়ন্ত্রণ করা যায়। নোঙর বিন্দু প্রক্রিয়া正是 এই নিয়ন্ত্রণের মূল মাধ্যম — মহাবিশ্বের গুরুত্বপূর্ণ বিন্দুগুলিতে স্থিতিশীল নোঙর বিন্দু প্রতিষ্ঠা করে, বিক্ষিপ্ত ব্যক্তিগত শক্তিকে সুশৃঙ্খল বিবর্তনের স্রোতে রূপান্তরিত করে, এবং শেষে মহাবিশ্বের সমগ্র মাত্রিক উন্নতি বাস্তবায়ন করে।</p><h2 id="_2-মহাবিশ্বের-গঠন-স্তর" tabindex="-1">2. মহাবিশ্বের গঠন স্তর <a class="header-anchor" href="#_2-মহাবিশ্বের-গঠন-স্তর" aria-label="Permalink to &quot;2. মহাবিশ্বের গঠন স্তর&quot;">​</a></h2><p>হেং ইয়ানঝোউ গঠনগতভাবে চারটি স্তরে বিভক্ত, এবং স্তরগুলোর মধ্যে কোনো বিচ্ছিন্নতা নেই, বরং নোঙর বিন্দু জালের মাধ্যমে পরস্পর সংযুক্ত:</p><table tabindex="0"><thead><tr><th>স্তর</th><th>নাম</th><th>বৈশিষ্ট্য</th><th>প্রধান বাসিন্দা</th></tr></thead><tbody><tr><td>প্রথম স্তর</td><td>বস্তুগত বিমান</td><td>ভৌতিক নিয়ম অনুসরণকারী বস্তুগত জগৎ, অসংখ্য গ্রহ ও ছায়াপথ অন্তর্ভুক্ত</td><td>মানব জাতি ও বেশিরভাগ বস্তুগত জীব</td></tr><tr><td>দ্বিতীয় স্তর</td><td>শক্তি স্তর</td><td>উচ্চ ঘনত্বের শক্তি সমন্বয় অঞ্চল, নিয়ম আংশিকভাবে প্রকাশ পায়</td><td>শক্তি জীব, সাধকের আত্মিক দেহ</td></tr><tr><td>তৃতীয় স্তর</td><td>চেতনা অঞ্চল</td><td>সমষ্টিগত চেতনা ও ব্যক্তিগত চেতনার মিলনস্থল তথ্য-স্থান</td><td>চেতনা সত্তা, উচ্চ-মাত্রিক অস্তিত্ব</td></tr><tr><td>চতুর্থ স্তর</td><td>নিয়ম জাল</td><td>মহাবিশ্বের মূল নিয়মের কার্যকরী স্তর, নোঙর বিন্দুর মূল ভিত্তি</td><td>নোঙর বিন্দু নিজেই, মহাবিশ্বের ইচ্ছাশক্তি</td></tr></tbody></table><p>চারটি স্তরের শক্তি ও তথ্য প্রবাহ &quot;নিচে প্রবেশ, উপরে সমন্বয়&quot; নীতি অনুসরণ করে: নিম্নস্তরের সাধনার ফলাফল উপরে নিয়ম জালে সমন্বিত হয়, এবং নিয়ম জালের স্থিতিশীল প্রতিক্রিয়া নিচে প্রতিটি স্তরের জীবকে পুষ্ট করে। নোঙর বিন্দু, স্তর-ব্যাপী সংযোগ কেন্দ্র হিসেবে, এই প্রবাহকে লুণ্ঠনমূলক আচরণ দ্বারা বিচ্ছিন্ন হওয়া থেকে রক্ষা করে।</p><h2 id="_3-মহাবিশ্বের-মূল-দ্বন্দ্ব" tabindex="-1">3. মহাবিশ্বের মূল দ্বন্দ্ব <a class="header-anchor" href="#_3-মহাবিশ্বের-মূল-দ্বন্দ্ব" aria-label="Permalink to &quot;3. মহাবিশ্বের মূল দ্বন্দ্ব&quot;">​</a></h2><p>হেং ইয়ানঝোউের মৌলিক দ্বন্দ্ব হলো &quot;লুণ্ঠন ও সহজীবন&quot; এর দ্বন্দ্ব। নোঙর বিন্দু প্রক্রিয়া সম্পূর্ণরূপে প্রতিষ্ঠার আগে, মহাবিশ্বে দীর্ঘকাল ধরে লুণ্ঠনমূলক সাধনা পদ্ধতি বিরাজমান ছিল — শক্তিশালীরা দুর্বলদের শক্তি, ভাগ্য এমনকি মূল উৎস গ্রাস করে নিজেদের বিবর্তন অর্জন করত, যার ফলে মহাবিশ্বের সমগ্র এনট্রপি বৃদ্ধি ত্বরান্বিত হয় এবং সভ্যতার বিচ্ছিন্নতা ঘন ঘন ঘটত। এই পদ্ধতি স্বল্পমেয়াদে কিছু শক্তিশালী সাধক তৈরি করতে পারে, কিন্তু দীর্ঘমেয়াদে এটি মহাবিশ্বের বিবর্তন সম্ভাবনাকে ক্ষয় করে ফেলে।</p><p>নোঙর সহজীবী সভ্যতার জন্ম正是 এই দ্বন্দ্বের প্রতিক্রিয়া। তিনশটি মূল সাধনা পদ্ধতি উন্মুক্ত করে, উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থা প্রতিষ্ঠা করে, এবং 20% সাধককে বিমানের সর্বোচ্চ শক্তিশালী হিসেবে সক্রিয় করার মাধ্যমে, সহজীবী সভ্যতা প্রমাণ করতে চায়: বিবর্তনের জন্য অন্যের বলি দেওয়ার প্রয়োজন নেই, এবং সমষ্টিগত সুশৃঙ্খল বিবর্তন ব্যক্তিগত লুণ্ঠনমূলক উন্নতির চেয়ে অনেক বেশি কার্যকর।</p><h2 id="_4-মহাবিশ্বের-বিকাশের-দিক" tabindex="-1">4. মহাবিশ্বের বিকাশের দিক <a class="header-anchor" href="#_4-মহাবিশ্বের-বিকাশের-দিক" aria-label="Permalink to &quot;4. মহাবিশ্বের বিকাশের দিক&quot;">​</a></h2><p>হেং ইয়ানঝোউের চূড়ান্ত দিক হলো &quot;হাজারো জাতির সহজীবন, মহাবিশ্বের মাত্রিক উন্নতি&quot;। এই দিকটি চার-পর্যায়ের পথ ধরে ধাপে ধাপে বাস্তবায়িত হয়:</p><ol><li><strong>বাস্তবতায় ভিত্তি স্থাপন</strong>: বস্তুগত বিমানে সহজীবী সামাজিক ব্যবস্থা প্রতিষ্ঠা করা, লুণ্ঠনের মূল কারণ দূরীকরণ</li><li><strong>প্রযুক্তি দ্বারা ক্ষমতায়ন</strong>: সাধনা নিয়মকে প্রযুক্তিগত প্রকৌশলের সাথে একত্রিত করা, বিবর্তনের প্রবেশদ্বার কমানো</li><li><strong>চেতনার বিবর্তন</strong>: জীব-রূপকে চেতনা অঞ্চলে স্থানান্তরিত করতে উদ্বুদ্ধ করা, মানসিক স্তরে সহজীবন বাস্তবায়ন</li><li><strong>আন্তঃনাক্ষত্রিক সহজীবন</strong>: বিমান-ব্যাপী ও নাক্ষত্র-ব্যাপী সম্পূর্ণ নোঙর বিন্দু জাল প্রতিষ্ঠা করা, মহাবিশ্বের সমগ্র মাত্রিক উন্নতি সম্পন্ন করা</li></ol><p>বর্তমানে হেং ইয়ানঝোউ প্রথম পর্যায় থেকে দ্বিতীয় পর্যায়ে রূপান্তরের গুরুত্বপূর্ণ সময়ে অবস্থিত, এবং নোঙর সহজীবী সভ্যতার বিভিন্ন ব্যবস্থা সম্পূর্ণরূপে বাস্তবায়িত হচ্ছে।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>হেং ইয়ানঝোউ কোনো স্থির মহাবিশ্ব নয়, বরং একটি বিবর্তনশীল জীবন্ত সম্প্রদায়। হেং ইয়ানঝোউ বোঝা মানে সহজীবী বিবর্তনের সম্ভাবনা বোঝা। এই সার্বিক পরিচিতিটি সমস্ত নথির সূচনা বিন্দু হিসেবে কাজ করবে, এবং পরবর্তী মডিউলগুলো নিয়ম, প্রক্রিয়া, সমাজ, আইন, জীবন, প্রযুক্তি, ইতিহাস, বিমান-ব্যাপী ইত্যাদি বিভিন্ন দিক থেকে বিস্তারিত আলোচনা করবে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (নোঙর সহজীবী সভ্যতার ঘোষণা)</li><li>03-共生文明宪章 (সহজীবী সভ্যতার সংবিধান)</li><li>10-三百套本源修炼体系总览 (তিনশটি মূল সাধনা পদ্ধতির সার্বিক পরিচিতি)</li></ul>',20)])])}const p=a(o,[["render",l]]);export{q as __pageData,p as default};
